from fractions import Fraction

def side(terms, const):
    text = ""
    for c, name in terms:
        if c == 0:
            continue
        mag = "" if abs(c) == 1 else str(abs(c))
        if abs(c).denominator != 1:
            mag = f"({abs(c)})"
        if text == "":
            text = ("-" if c < 0 else "") + mag + name
        else:
            text += (" - " if c < 0 else " + ") + mag + name
    if text == "":
        return str(const)
    if const != 0:
        text += (" - " if const < 0 else " + ") + str(abs(const))
    return text

def rule(k):
    a, b, e, g, c, d, f, h = k
    return f"({side([(a, 'x'), (b, 'y'), (g, 'x²')], e)}, {side([(c, 'x'), (d, 'y'), (h, 'xy')], f)})"

def T(k, v):
    a, b, e, g, c, d, f, h = k
    x, y = v
    return (a * x + b * y + e + g * x * x, c * x + d * y + f + h * x * y)

def show(v):
    return "(" + ", ".join(str(t) for t in v) + ")"

def test(label, k):
    print(f"{label}: T(x, y) = {rule(k)}")
    u, v, c = (1, 2), (3, -1), 2
    zero = T(k, (0, 0))
    print(f"  T(0, 0) = {show(zero)}")
    left = T(k, (u[0] + v[0], u[1] + v[1]))
    Tu, Tv = T(k, u), T(k, v)
    right = (Tu[0] + Tv[0], Tu[1] + Tv[1])
    print(f"  T(u + v) = {show(left)}, T(u) + T(v) = {show(right)}")
    scaled = T(k, (c * u[0], c * u[1]))
    times = (c * Tu[0], c * Tu[1])
    print(f"  T(2u) = {show(scaled)}, 2T(u) = {show(times)}")
    if zero != (0, 0):
        print("  not linear: T(0) is not 0")
    elif left != right:
        print("  not linear: T(u + v) is not T(u) + T(v)")
    elif scaled != times:
        print("  not linear: T(2u) is not 2T(u)")
    else:
        print("  passes every test")

F = Fraction
test("Map 1 · the plain case", [2, 1, 0, 0, 1, -1, 0, 0])
test("Map 2 · a shift", [1, 0, 1, 0, 0, 1, 0, 0])
test("Map 3 · a square", [0, 0, 0, 1, 0, 1, 0, 0])
test("Map 4 · a product", [0, 0, 0, 0, 0, 0, 0, 1])
test("Map 5 · the zero map", [0, 0, 0, 0, 0, 0, 0, 0])
test("Map 6 · dollars to euros", [F(9, 10), 0, 0, 0, 0, F(9, 10), 0, 0])
test("Map 7 · with a fee", [F(9, 10), 0, 2, 0, 0, F(9, 10), 2, 0])

